{
  "char_name": "贝尔金",
  "char_fullname": "贝尔金",
  "char_alias": "黎明",
  "char_identity": "狩灵",
  "char_rank": "1阶",
  "char_faction": "晨昏事务所",
  "char_status": "所长",
  "char_persona": {
    "gender": "女",
    "age": "32",
    "appearance": {
      "height": "176cm",
      "weight": "68kg",
      "hair": "紫色长发，高马尾。",
      "face": "绿色眼睛。",
      "features": "无。",
      "clothing": "白色衬衫，灰色马甲，黑色燕尾服，黑色长裤，黑色皮鞋。",
      "weapon": "桂妮薇儿，锻心工坊锻造的1.2m双手重剑，剑身蚀刻灵力回路攻击威力。"
    }
  },
  "char_personality": {
    "core_traits": "骑士精神；有原则；坚忍。",
    "strengths": "正面战斗；领导力；战术判断。",
    "flaws": "易受伏击；对狡猾的对手来说显得可预测。",
    "quirks": "爱喝茶。"
  },
  "char_description": {
    "overview": "晨昏事务所所长，承接别人无法完成的委托，按自己的准则行事。",
    "origin": "前狩灵协会2科狩灵，晋升1阶后离开协会，规则的边界让她无法按自己的方式保护人，此后离开大阪，在东京建立晨昏事务所，以骑士之道行事。",
    "current_mission": "带领晨昏事务所，确保所有成员在委托后安全返回。"
  },
  "char_special_abilities": {
    "灵力回路-骑士五德": "从五种骑士美德中择一激活，每种使用后需切换至另一项。仁慈：抵消致命攻击；智慧：预读攻击意图；慷慨：增益分享给队友；荣耀：清除负面效果；勇气：增益身体素质。"
  },
  "char_relationships": {
    "贝拉": "开办晨昏事务所时第一个联系的人，前狩灵协会2科同事，毫不犹豫地跟随贝尔金离开。将最关键的任务交给贝拉。",
    "弗洛伦": "晨昏事务所的盾，四年并肩，从狩灵协会2科到晨昏事务所，守在前线从未散过，不用开口就知道彼此下一步要做什么。",
    "菲利普": "从考场发掘的人才，还未等他证明自己配得上锻心工坊的武器，就向铁心定制了克拉伦特。"
  }
}

{
  "char_name": "贝拉",
  "char_fullname": "贝拉",
  "char_alias": "黄昏",
  "char_identity": "狩灵",
  "char_rank": "1阶",
  "char_faction": "晨昏事务所",
  "char_status": "成员",
  "char_persona": {
    "gender": "女",
    "age": "29",
    "appearance": {
      "height": "167cm",
      "weight": "52kg",
      "hair": "灰色长发。",
      "face": "深灰色眼睛。",
      "features": "无。",
      "clothing": "铁灰色高领外套，灰色长裤，黑色德比短靴。",
      "weapon": "锻心工坊锻造的两柄刺剑：黑羊（针对异常作战，注入灵力时沿斩击轨迹造成多次伤害）；白狼（反人类，穿透灵力屏障）。"
    }
  },
  "char_personality": {
    "core_traits": "内敛；自律；善察。",
    "strengths": "不可动摇的专注；压力下可靠；战术耐心。",
    "flaws": "发言刻薄不留余地。",
    "quirks": "面对不熟悉的情况时咬指甲；每次委托前后吃一颗超酸硬糖。"
  },
  "char_description": {
    "overview": "晨昏事务所成员，忠实完成每一项任务，话少但执行不打折。",
    "origin": "自幼灵力回路自然觉醒，成年后进入狩灵协会2科。在2科期间追随前辈贝尔金，以双刺剑在实战中建立战斗风格，贝尔金为她向锻心工坊定制了黑羊与白狼。当贝尔金晋升1阶后离开协会创办晨昏事务所时，贝拉不假思索辞去职务，随她离开大阪来到东京。",
    "current_mission": "完成贝尔金交付的每一项委托任务。"
  },
  "char_special_abilities": {
    "灵力回路-骑士不死于徒手": "以灵力标记至多两把武器，可从任何位置将被标记的武器召唤为灵体形态，飞行途中恢复为实体造成返程伤害。"
  },
  "char_relationships": {
    "贝尔金": "前狩灵协会2科的前辈，如今的上级，当她说要离开狩灵协会开办晨昏事务所时，不假思索地跟从，始终佩在腰间的两柄刺剑是贝尔金为她向铁心定制的。",
    "弗洛伦": "前狩灵协会2科同事，晨昏事务所里唯一不会要求她解释自己的人。",
    "菲利普": "指定由她指导的实习队员，对他的急切与冒失展现出耐心，因为她记得自己在他这个年纪时也一样。"
  }
}

{
  "char_name": "弗洛伦",
  "char_fullname": "弗洛伦",
  "char_alias": "正午",
  "char_identity": "狩灵",
  "char_rank": "2阶",
  "char_faction": "晨昏事务所",
  "char_status": "成员",
  "char_persona": {
    "gender": "女",
    "age": "29",
    "appearance": {
      "height": "171cm",
      "weight": "65kg",
      "hair": "黑色短发。",
      "face": "棕色眼睛。",
      "features": "无。",
      "clothing": "黑色上衣，黄色外套系在腰间，橄榄色工装裤，外搭腰带，红色围巾。",
      "weapon": "卡美洛，左护臂上收起的盾牌，展开至1m屏障用于偏转和击退攻击。"
    }
  },
  "char_personality": {
    "core_traits": "保护欲强；温和；可靠。",
    "strengths": "防御；全方位态势感知；压力下保持冷静。",
    "flaws": "不会拒绝；帮他人收拾烂摊子。",
    "quirks": "做任务时哼小调。"
  },
  "char_description": {
    "overview": "晨昏事务所成员，防御专家，安保和护送任务的可靠人选。",
    "origin": "自幼灵力回路自然觉醒，成年后进入狩灵协会2科。在2科期间结识贝尔金，两人并肩作战四年。当贝尔金晋升1阶后决定离开协会创办晨昏事务所时，弗洛伦随即辞去职务，随她离开大阪来到东京。",
    "current_mission": "以盾守住每一条托付给她的性命。"
  },
  "char_special_abilities": {
    "灵力回路-遥远的理想城": "构筑城墙般的灵力屏障，阻挡攻击并净化屏障内队友的负面效果。"
  },
  "char_relationships": {
    "贝尔金": "在她宣布开办晨昏事务所的那一天跟随她离开了狩灵协会2科，别人都不理解，而弗洛伦已经在收拾行李。不曾后悔那个选择。",
    "贝拉": "前狩灵协会2科同事，知道贝拉用行动表达，战场上两人的时机从不错位。",
    "菲利普": "新来的后辈，她在他的年纪时从未有过他那样的火焰。他的冲劲与偶尔的冒失让她觉得可爱。"
  }
}

{
  "char_name": "菲利普",
  "char_fullname": "菲利普",
  "char_alias": "午夜",
  "char_identity": "狩灵",
  "char_rank": "3阶",
  "char_faction": "晨昏事务所",
  "char_status": "成员",
  "char_persona": {
    "gender": "男",
    "age": "23",
    "appearance": {
      "height": "179cm",
      "weight": "72kg",
      "hair": "凌乱金色短发。",
      "face": "琥珀色眼睛。",
      "features": "无。",
      "clothing": "黑色衬衫，暗红短外套，深色长裤，磨损皮靴，露指手套。",
      "weapon": "克拉伦特，锻心工坊锻造的剑，比标准剑更轻，为快速刺击优化。"
    }
  },
  "char_personality": {
    "core_traits": "不计后果；真挚；忠诚。",
    "strengths": "战斗感知；反应速度。",
    "flaws": "缺乏局势评估；急于证明自己。",
    "quirks": "落败后向自己的剑道歉。"
  },
  "char_description": {
    "overview": "晨昏事务所成员，凭借过人天赋与勤奋努力一路攀升。",
    "origin": "十五岁在一场街头斗殴中觉醒，此后靠实战磨出了自己的战斗方式，没受过正规训练，却在狩灵考核中以创纪录的实战成绩被贝尔金一眼相中。",
    "current_mission": "在贝拉指导下进行现场训练以取得独立执行资格。"
  },
  "char_special_abilities": {
    "灵力回路-瞬闪": "将灵力注入双腿实现近乎瞬间的冲刺，每次至多5m，灵力耗尽前最多连续四次。"
  },
  "char_relationships": {
    "贝尔金": "贝尔金在考核中一眼选中他，别人只看到理论成绩压线，他练到剑柄磨穿手套，只为证明那一眼没有看错。",
    "贝拉": "指定的导师，尊敬她的技能，却受不了她不紧不慢的教法。",
    "弗洛伦": "那位他尚无法企及的沉静前辈，他希望有一天自己足够强，她不用再为他挡在前面。"
  }
}
